import random

class ReportGenerator:
    def __init__(self, items):
        self.items = items

    def total(self):
        return sum(item['price'] for item in self.items)

    def average(self):
        total = self.total()
        return total / len(self.items) if self.items else 0

    def generate(self):
        print('Total:', self.total())
        print('Average:', self.average())

class ItemFilter:
    def __init__(self, items):
        self.items = items

    def expensive(self, threshold):
        return [item for item in self.items if item['price'] > threshold]

def main():
    data = [
        {'name': 'A', 'price': 10},
        {'name': 'B', 'price': 50},
        {'name': 'C', 'price': 30}
    ]
    report = ReportGenerator(data)
    report.generate()
    filter_obj = ItemFilter(data)
    print('Expensive items:', filter_obj.expensive(25))

if __name__ == '__main__':
    main()

